OPTS = [{}, {"delimiter": ";"}, {"quotechar": "'"}, {"skipinitialspace": True}, {"escapechar": "\\"},
        {"doublequote": False, "escapechar": "\\"}, {"quoting": csv.QUOTE_NONE, "escapechar": "\\"}, {"quoting": csv.QUOTE_ALL},
        {"strict": True}, {"quoting": csv.QUOTE_NONE}, {"quoting": csv.QUOTE_NONNUMERIC}, {"lineterminator": "\n", "quotechar": "'", "delimiter": ";"}]
class W:
    def __init__(self): self.s = ""
    def write(self, t): self.s += t; return len(t)
for i, (text, row) in enumerate(DATA):
    opt = OPTS[i % len(OPTS)]
    lines = text.splitlines(True)
    try:
        r = list(csv.reader(lines, **opt))
    except (csv.Error, ValueError) as e:
        r = type(e).__name__ + " " + str(e)
    print("R", i, opt, repr(text), r)
    w = W()
    wopt = dict(opt)
    wopt.pop("strict", None)
    try:
        csv.writer(w, **wopt).writerow(row)
        out = w.s
    except csv.Error as e:
        out = "Error " + str(e)
    print("W", i, repr(row), repr(out))
